JavaAutoAppletLocator_AC(	const JMAppletLocatorCallbacks* callbacks,								JMClientData clientData,								const CStr255_AC&	url,								const CStr255_AC&	htmlText = kEmptyString_AC);		// Locate an applet asynchronously by fetching an HTML document from a specified URL.	CJavaAutoAppletLocator_AC(	JMClientData clientData,								const CTempJavaAppletLocator_AC& locator);		// Locate an applet synchronously using CTempJavaAppletLocator_AC.	~CJavaAutoAppletLocator_AC()	{ }};//----------------------------------------------------------------------------------------// CJavaAppletContainer_AC//----------------------------------------------------------------------------------------class EXPORT_AC CJavaAppletContainer_AC{	public:	CJavaAppletContainer_AC(const CStr255_AC&	url,							const CStr255_AC&	htmlText = kEmptyString_AC);	CJavaAppletContainer_AC(const CTempJavaAppletLocator_AC& locator);		virtual ~CJavaAppletContainer_AC();		CStr255_AC GetURL() const;		JMAppletLocatorRef GetAppletLocator();				virtual UInt32 CountApplets();	virtual CLongRect_AC GetAppletBounds(UInt32 appletIndex);	virtual CStr255_AC GetAppletName(UInt32 appletIndex);	virtual JMTextRef GetAppletTag(UInt32 appletIndex);	virtual void LocatorCompleted(JMLocatorErrors error);	virtual void AddContext(CJavaAppletContext_AC* aJavaAppletContext);	virtual void RemoveContext(CJavaAppletContext_AC* aJavaAppletContext);	CJavaAppletContext_AC* GetLastContext();		void StartAllApplets();		// Creates a context for each applet.		virtual CJavaAppletContext_AC* DoMakeContext(UInt32 appletIndex);		// Factory method that creates a context for the indexed applet.		virtual void ReportError(const CStr255_AC& errorMsg, const CStr255_AC& urlText);		// Reports an error. This calls ProgramReport_AC by default.private:	CStr255_AC				fURL;	CJavaAutoAppletLocator_AC fAppletLocator;	CAutoPtr_AC<CList_AC>	fContextList;	static JMAppletLocatorCallbacks	fgAppletCallbacks;};extern "C" void LocatorCompletedProc(JMAppletLocatorRef ref, JMLocatorErrors status);//----------------------------------------------------------------------------------------// CJavaAutoAppletContainer_AC//----------------------------------------------------------------------------------------class EXPORT_AC CJavaAutoAppletContainer_AC : public CJavaAppletContainer_AC{public:	CJavaAutoAppletContainer_AC(const CStr255_AC& url, const CStr255_AC& htmlText = kEmptyString_AC);	CJavaAutoAppletContainer_AC(const CTempJavaAppletLocator_AC& locator);	virtual ~CJavaAutoAppletContainer_AC();		virtual void LocatorCompleted(JMLocatorErrors error);};#endif // __CJavaAppletContainer_AC__